-- Self-contained salon invitations, authorization and finance privacy. All fixtures roll back.
begin;
create temp table invite_ids(key text primary key,id uuid);
insert into invite_ids values('owner','b71f0000-0000-4000-8000-000000000001'),('barber','b71f0000-0000-4000-8000-000000000002'),('other','b71f0000-0000-4000-8000-000000000003'),('customer','b71f0000-0000-4000-8000-000000000004'),('replacement','b71f0000-0000-4000-8000-000000000005');
insert into auth.users(id,email)select id,key||'-invite-fixture@example.invalid'from invite_ids;
insert into invite_ids values('salon',gen_random_uuid()),('salon2',gen_random_uuid()),('chair',gen_random_uuid()),('chair2',gen_random_uuid()),('invitation',gen_random_uuid()),('replacement_invite',gen_random_uuid()),('third_invite',gen_random_uuid());
create function pg_temp.i(k text)returns uuid language sql stable as $$select id from pg_temp.invite_ids where key=k$$;
create function pg_temp.ok(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.denied(statement text,expected text default '42501')returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=expected then return;end if;raise exception 'Expected %, got %: %',expected,sqlstate,sqlerrm;end;raise exception 'Unauthorized operation succeeded: %',statement;end;$$;
do $$begin execute format('grant usage on schema %I to authenticated,anon',pg_my_temp_schema()::regnamespace);end;$$;
grant all on invite_ids to authenticated;
set local role anon;
select pg_temp.denied($q$select public.barber_invitation('accept','{}')$q$);
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('owner'))::text,true);
set local role authenticated;
select public.manager_command('create_salon',jsonb_build_object('id',pg_temp.i('salon'),'name','Invitation fixture','address','Akurana','opens_at','00:00','closes_at','23:59','weekdays','[0,1,2,3,4,5,6]'::jsonb));
select public.manager_command('create_salon',jsonb_build_object('id',pg_temp.i('salon2'),'name','Other invitation fixture','address','Akurana','opens_at','00:00','closes_at','23:59','weekdays','[0,1,2,3,4,5,6]'::jsonb));
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.i('chair'),'salon_id',pg_temp.i('salon'),'display_name','Invited chair','specialities','[]'::jsonb));
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.i('chair2'),'salon_id',pg_temp.i('salon2'),'display_name','Other chair','specialities','[]'::jsonb));
select public.barber_invitation('create',jsonb_build_object('id',pg_temp.i('invitation'),'salon_id',pg_temp.i('salon'),'barber_id',pg_temp.i('chair'),'token',repeat('a',64)));
select public.barber_invitation('create',jsonb_build_object('id',pg_temp.i('invitation'),'salon_id',pg_temp.i('salon'),'barber_id',pg_temp.i('chair'),'token',repeat('a',64)));
select pg_temp.ok(public.barber_team(pg_temp.i('salon'))->'members'->0->'invitation'->>'status'='pending','Owner sees pending invitation');
select pg_temp.ok(public.barber_team(pg_temp.i('salon'))::text not like '%token%','Team API returns no invitation secrets');
select pg_temp.denied('select * from bookmyturn_private.barber_invitations');
select pg_temp.denied($q$select public.barber_invitation('accept',jsonb_build_object('token',repeat('a',64)))$q$,'P0001');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('barber'))::text,true);
select pg_temp.denied($q$select public.barber_team(pg_temp.i('salon'))$q$);
select pg_temp.denied($q$select public.barber_invitation('create',jsonb_build_object('id',gen_random_uuid(),'salon_id',pg_temp.i('salon'),'barber_id',pg_temp.i('chair'),'token',repeat('f',64)))$q$);
select pg_temp.denied($q$select public.barber_invitation('accept',jsonb_build_object('token',repeat('b',64)))$q$,'P0001');
select pg_temp.ok(public.barber_invitation('preview',jsonb_build_object('token',repeat('a',64)))->>'barber_name'='Invited chair','Secret preview shows intended chair');
select pg_temp.ok(jsonb_array_length(public.barber_context())=0,'Preview creates no membership');
select public.barber_invitation('accept',jsonb_build_object('token',repeat('a',64),'salon_id',pg_temp.i('salon2'),'barber_id',pg_temp.i('chair2'),'role','owner','permissions','["read_finance"]'::jsonb));
select public.barber_invitation('accept',jsonb_build_object('token',repeat('a',64)));
select pg_temp.ok(jsonb_array_length(public.barber_context())=1 and public.barber_context()->0->>'barber_id'=pg_temp.i('chair')::text,'Acceptance and retry assign exactly the invitation chair');
select pg_temp.ok(not bookmyturn_private.has_permission(pg_temp.i('salon'),'read_finance'),'Client cannot grant itself finance');
select pg_temp.ok(jsonb_array_length(public.manager_state()->'salons')=0,'Barber is not an owner');
select pg_temp.denied($q$select public.barber_state(pg_temp.i('chair2'))$q$);
select pg_temp.denied($q$select bookmyturn_private.barber_state_with_finance(pg_temp.i('chair'))$q$);
select pg_temp.denied($q$select bookmyturn_private.barber_state_pre_haircuts(pg_temp.i('chair'))$q$);
select pg_temp.ok(not(public.barber_state(pg_temp.i('chair'))->'performance'?'today_revenue_minor'),'Barber RPC removes revenue totals');
select pg_temp.denied($q$select public.barber_invitation('create',jsonb_build_object('id',gen_random_uuid(),'salon_id',pg_temp.i('salon2'),'barber_id',pg_temp.i('chair2'),'token',repeat('f',64)))$q$);
select pg_temp.denied($q$select public.manager_command('salon',jsonb_build_object('salon_id',pg_temp.i('salon'),'name','Unauthorized name'))$q$);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('customer'))::text,true);
insert into invite_ids select 'queue',(public.customer_command('join_queue',jsonb_build_object('salon_id',pg_temp.i('salon'),'barber_id',pg_temp.i('chair'),'request_key',gen_random_uuid(),'present',false))->>'id')::uuid;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('barber'))::text,true);
select public.barber_command(pg_temp.i('chair'),'check_in',jsonb_build_object('reference',(select q->>'reference'from jsonb_array_elements(public.barber_state(pg_temp.i('chair'))->'queues')q where q->>'id'=pg_temp.i('queue')::text)));
insert into invite_ids select 'session',(public.barber_command(pg_temp.i('chair'),'start_haircut',jsonb_build_object('id',pg_temp.i('queue')))->>'id')::uuid;
select pg_temp.ok((select count(*)=0 from bookmyturn_private.sales),'Start creates no readable sale');
select public.barber_command(pg_temp.i('chair'),'finish_haircut',jsonb_build_object('id',pg_temp.i('session'),'final_amount_minor',125000));
select public.barber_command(pg_temp.i('chair'),'finish_haircut',jsonb_build_object('id',pg_temp.i('session'),'final_amount_minor',999));
select pg_temp.ok(not(public.barber_state(pg_temp.i('chair'))->'sessions'->0?'final_amount_minor'),'Barber history omits financial fields');
select pg_temp.ok((public.barber_state(pg_temp.i('chair'))->'performance'->>'today_count')::int=1,'Nonfinancial completed count retained');
select pg_temp.ok((select count(*)=0 from public.service_sessions),'Direct session read cannot bypass financial masking');
select pg_temp.ok((select count(*)=0 from public.service_items),'Direct line items do not leak prices');
select pg_temp.ok((select count(*)=0 from bookmyturn_private.sales),'Barber cannot read sales');
select pg_temp.ok((select count(*)=0 from bookmyturn_private.expenses),'Barber cannot read expenses');
select pg_temp.ok((select count(*)=0 from bookmyturn_private.commission_accruals),'Barber cannot read commission');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('other'))::text,true);
select pg_temp.denied($q$select public.barber_invitation('accept',jsonb_build_object('token',repeat('a',64)))$q$,'P0001');
select pg_temp.denied($q$select public.barber_invitation('revoke',jsonb_build_object('salon_id',pg_temp.i('salon'),'barber_id',pg_temp.i('chair')))$q$);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('owner'))::text,true);
select pg_temp.ok((select count(*)=1 from bookmyturn_private.sales where service_session_id=pg_temp.i('session')and amount_minor=125000),'Owner retains exactly one sale');
select pg_temp.ok(public.barber_team(pg_temp.i('salon'))->'members'->0->>'connected'='true','Owner sees connected account');
select public.barber_invitation('revoke',jsonb_build_object('salon_id',pg_temp.i('salon'),'barber_id',pg_temp.i('chair')));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('barber'))::text,true);
select pg_temp.denied($q$select public.barber_state(pg_temp.i('chair'))$q$);
select pg_temp.denied($q$select public.barber_invitation('accept',jsonb_build_object('token',repeat('a',64)))$q$,'P0001');
select pg_temp.ok((select count(*)=0 from public.queue_entries),'Revoked account cannot read customer records');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('owner'))::text,true);
select public.barber_invitation('create',jsonb_build_object('id',pg_temp.i('replacement_invite'),'salon_id',pg_temp.i('salon'),'barber_id',pg_temp.i('chair'),'token',repeat('b',64)));
select public.barber_invitation('create',jsonb_build_object('id',pg_temp.i('third_invite'),'salon_id',pg_temp.i('salon'),'barber_id',pg_temp.i('chair'),'token',repeat('c',64)));
select pg_temp.denied($q$select public.barber_invitation('create',jsonb_build_object('id',pg_temp.i('replacement_invite'),'salon_id',pg_temp.i('salon'),'barber_id',pg_temp.i('chair'),'token',repeat('b',64)))$q$,'P0001');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('replacement'))::text,true);
select pg_temp.denied($q$select public.barber_invitation('accept',jsonb_build_object('token',repeat('b',64)))$q$,'P0001');
select public.barber_invitation('accept',jsonb_build_object('token',repeat('c',64)));
select pg_temp.ok(public.barber_context()->0->>'barber_id'=pg_temp.i('chair')::text,'Replacement account uses existing chair');
reset role;
-- Expired and cancelled links never grant access, even before any acceptance.
update bookmyturn_private.barber_invitations set accepted_at=null,accepted_by=null,expires_at=clock_timestamp()-interval '1 second',created_at=clock_timestamp()-interval '8 days'where id=pg_temp.i('third_invite');
set local role authenticated;
select pg_temp.denied($q$select public.barber_invitation('accept',jsonb_build_object('token',repeat('c',64)))$q$,'P0001');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('owner'))::text,true);
select public.barber_invitation('cancel',jsonb_build_object('salon_id',pg_temp.i('salon'),'barber_id',pg_temp.i('chair'),'id',pg_temp.i('third_invite')));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('replacement'))::text,true);
select pg_temp.denied($q$select public.barber_invitation('preview',jsonb_build_object('token',repeat('c',64)))$q$,'P0001');
reset role;
select pg_temp.ok((select count(*)=1 from bookmyturn_private.salon_memberships where barber_id=pg_temp.i('chair')),'No duplicate chair memberships');
select pg_temp.ok(not exists(select 1 from bookmyturn_private.audit_events where salon_id=pg_temp.i('salon')and changes::text like '%token_hash%'),'Audit does not store secret hashes');
select 'PASS: invitations, retries, isolation, revocation, replacement and financial privacy' as result;
rollback;
